  "Saving file\u2026": "\u6b63\u5728\u4fdd\u5b58\u6587\u4ef6\u2026",
  "File sent": "\u6587\u4ef6\u5df2\u53d1\u9001",
  "Upload failed. Select Send file to retry.": "\u4e0a\u4f20\u5931\u8d25\uff0c\u8bf7\u9009\u62e9\u53d1\u9001\u6587\u4ef6\u91cd\u8bd5\u3002",
  "Upload stopped. Check the conversation before retrying.": "\u4e0a\u4f20\u5df2\u505c\u6b62\u3002\u91cd\u8bd5\u524d\u8bf7\u68c0\u67e5\u804a\u5929\u8bb0\u5f55\u3002",
  "Choose a file between 1 byte and 10 MB": "\u8bf7\u9009\u62e9 1 \u5b57\u8282\u81f3 10 MB \u7684\u6587\u4ef6",
  "Choose a file with a valid name of at most 180 characters": "\u8bf7\u9009\u62e9\u540d\u79f0\u6709\u6548\u4e14\u4e0d\u8d85\u8fc7 180 \u4e2a\u5b57\u7b26\u7684\u6587\u4ef6",
  "File storage is full": "\u6587\u4ef6\u5b58\u50a8\u7a7a\u95f4\u5df2\u6ee1",
  "Your shared files have reached the 50 MB or 100-file limit": "\u4f60\u7684\u5171\u4eab\u6587\u4ef6\u5df2\u8fbe\u5230 50 MB \u6216 100 \u4e2a\u6587\u4ef6\u7684\u9650\u5236",
  "Another file is uploading. Please wait": "\u53e6\u4e00\u4e2a\u6587\u4ef6\u6b63\u5728\u4e0a\u4f20\uff0c\u8bf7\u7a0d\u5019",
