  "A note, a thought, a hello": "\u7559\u8a00\u3001\u60f3\u6cd5\u3001\u95ee\u5019",
  "Leave a little kindness.": "\u7559\u4e0b\u4e00\u4efd\u5584\u610f\u3002",
  "Notes on this page are public. Keep private conversations in Messages.": "\u6b64\u9875\u7559\u8a00\u516c\u5f00\u53ef\u89c1\uff0c\u79c1\u5bc6\u4ea4\u6d41\u8bf7\u4f7f\u7528\u79c1\u4fe1\u3002",
  "Loading notes\u2026": "\u6b63\u5728\u52a0\u8f7d\u7559\u8a00\u2026",
