  "Films, match days, music videos \u2014 a little room for your people.": "\u7535\u5f71\u3001\u7403\u8d5b\u3001\u97f3\u4e50\u89c6\u9891\uff0c\u4e3a\u4f19\u4f34\u7559\u4e00\u95f4\u5c0f\u5c4b\u3002",
  "Shared playback, live conversation and messages across the screen.": "\u540c\u6b65\u64ad\u653e\u3001\u5b9e\u65f6\u804a\u5929\uff0c\u8fd8\u6709\u5c4f\u5e55\u5f39\u5e55\u3002",
