  "YouTube links or direct MP4, WebM and m3u8 links. Members of your university can join.": "\u652f\u6301 YouTube \u6216 MP4\u3001WebM\u3001m3u8 \u76f4\u94fe\uff0c\u672c\u6821\u6210\u5458\u53ef\u52a0\u5165\u3002",
