  "A little corner of campus, made by me.": "\u6211\u7684\u6821\u56ed\u5c0f\u5929\u5730\u3002",
  "No introduction yet. Every good connection starts with a hello.": "\u6682\u65e0\u4ecb\u7ecd\uff0c\u6bcf\u6bb5\u7f8e\u597d\u7684\u8054\u7cfb\u90fd\u4ece\u4e00\u53e5\u95ee\u5019\u5f00\u59cb\u3002",
  "Your friend\u2019s video": "\u597d\u53cb\u7684\u89c6\u9891\u753b\u9762",
  "Your camera preview": "\u4f60\u7684\u6444\u50cf\u5934\u9884\u89c8",
