  "Which university is in Canberra?": "\u54ea\u6240\u5927\u5b66\u4f4d\u4e8e\u582a\u57f9\u62c9\uff1f",
  "How many sides does a hexagon have?": "\u516d\u8fb9\u5f62\u6709\u51e0\u6761\u8fb9\uff1f",
  "Which planet is called the Red Planet?": "\u54ea\u9897\u884c\u661f\u88ab\u79f0\u4e3a\u7ea2\u8272\u661f\u7403\uff1f",
  "Which city is UWA based in?": "\u897f\u6fb3\u5927\u5b66\u4f4d\u4e8e\u54ea\u5ea7\u57ce\u5e02\uff1f",
  "What is the chemical symbol for gold?": "\u91d1\u7684\u5316\u5b66\u7b26\u53f7\u662f\u4ec0\u4e48\uff1f",
  "Which university uses purple as a signature colour?": "\u54ea\u6240\u5927\u5b66\u4ee5\u7d2b\u8272\u4e3a\u6807\u5fd7\u8272\uff1f",
  "Which ocean lies to the west of Australia?": "\u6fb3\u5927\u5229\u4e9a\u897f\u4fa7\u662f\u54ea\u7247\u6d77\u6d0b\uff1f",
  "How many squares are on a chessboard?": "\u56fd\u9645\u8c61\u68cb\u68cb\u76d8\u6709\u591a\u5c11\u683c\uff1f",
  "What is 7 \u00d7 8?": "7 \u00d7 8 \u7b49\u4e8e\u591a\u5c11\uff1f",
  "Which instrument usually has 88 keys?": "\u54ea\u79cd\u4e50\u5668\u901a\u5e38\u6709 88 \u4e2a\u952e\uff1f",
  "What does HTML describe?": "HTML \u63cf\u8ff0\u4ec0\u4e48\uff1f",
  "Which piece moves in an L shape in chess?": "\u56fd\u9645\u8c61\u68cb\u4e2d\u54ea\u4e2a\u68cb\u5b50\u8d70 L \u5f62\uff1f",
  "What is the capital of Queensland?": "\u6606\u58eb\u5170\u5dde\u7684\u9996\u5e9c\u662f\u54ea\u91cc\uff1f",
  "Which is a renewable energy source?": "\u54ea\u4e00\u79cd\u662f\u53ef\u518d\u751f\u80fd\u6e90\uff1f",
  "What is the largest mammal?": "\u6700\u5927\u7684\u54fa\u4e73\u52a8\u7269\u662f\u4ec0\u4e48\uff1f",
  "Which direction does the sun generally rise from?": "\u592a\u9633\u901a\u5e38\u4ece\u54ea\u4e2a\u65b9\u5411\u5347\u8d77\uff1f",
