  "Open the account menu (your photo) and choose your name to change your photo and introduction.": "\u6253\u5f00\u8d26\u6237\u83dc\u5355\uff08\u4f60\u7684\u5934\u50cf\uff09\uff0c\u70b9\u4f60\u7684\u540d\u5b57\u5373\u53ef\u66f4\u6362\u5934\u50cf\u548c\u81ea\u6211\u4ecb\u7ecd\u3002",
  "Open the account menu (your photo, or Settings when signed out) and pick a language.": "\u6253\u5f00\u8d26\u6237\u83dc\u5355\uff08\u4f60\u7684\u5934\u50cf\uff1b\u672a\u767b\u5f55\u65f6\u4e3a\u201c\u8bbe\u7f6e\u201d\uff09\uff0c\u7136\u540e\u9009\u62e9\u8bed\u8a00\u3002",
  "Choose your university on the home page, or go straight to it when only one is open. You can browse without an account.": "\u5728\u9996\u9875\u9009\u62e9\u4f60\u7684\u5927\u5b66\uff1b\u5982\u679c\u53ea\u5f00\u653e\u4e86\u4e00\u6240\uff0c\u4f1a\u76f4\u63a5\u8fdb\u5165\u3002\u65e0\u9700\u8d26\u53f7\u5373\u53ef\u6d4f\u89c8\u3002",
