  "WELCOME BACK": "\u6b22\u8fce\u56de\u6765",
  "Sign in to CampusWall.": "\u767b\u5f55 CampusWall\u3002",
  "New here? Create an account": "\u7b2c\u4e00\u6b21\u6765\uff1f\u521b\u5efa\u8d26\u53f7",
  "\u2014 Fictional activities at real campus venues. All test posters are labelled. Photos are illustrative.": "\u2014 \u5728\u771f\u5b9e\u6821\u56ed\u5730\u70b9\u865a\u6784\u7684\u6d4b\u8bd5\u6d3b\u52a8\u3002\u6240\u6709\u6d4b\u8bd5\u6d77\u62a5\u90fd\u6709\u6807\u6ce8\uff0c\u7167\u7247\u4ec5\u4f5c\u793a\u610f\u3002",
  "CampusWall test collection": "CampusWall \u6d4b\u8bd5\u5408\u96c6",
