  "Arts & performance": "\u827a\u672f\u4e0e\u8868\u6f14",
  "Music, dance, film & creativity": "\u97f3\u4e50\u3001\u821e\u8e48\u3001\u7535\u5f71\u4e0e\u521b\u4f5c",
  "Culture & languages": "\u6587\u5316\u4e0e\u8bed\u8a00",
