  "Gaming, books & niche interests": "\u6e38\u620f\u3001\u8bfb\u4e66\u4e0e\u5c0f\u4f17\u7231\u597d",
  "Volunteering & community": "\u5fd7\u613f\u670d\u52a1\u4e0e\u793e\u533a",
