  "Politics & advocacy": "\u653f\u6cbb\u4e0e\u5021\u5bfc",
  "Debate, campaigns & causes": "\u8fa9\u8bba\u3001\u6d3b\u52a8\u4e0e\u516c\u76ca\u8bae\u9898",
  "Social & campus life": "\u793e\u4ea4\u4e0e\u6821\u56ed\u751f\u6d3b",
