  "All clubs": "\u5168\u90e8\u793e\u56e2",
  "Browse the complete campus directory": "\u6d4f\u89c8\u5b8c\u6574\u7684\u6821\u56ed\u793e\u56e2\u540d\u5f55",
  "Start with an interest above, or search for a club you already have in mind.": "\u5148\u5728\u4e0a\u9762\u9009\u4e00\u4e2a\u5174\u8da3\uff0c\u6216\u8005\u76f4\u63a5\u641c\u7d22\u4f60\u60f3\u627e\u7684\u793e\u56e2\u3002",
  "Explore the games freely. Sign in to create a room, join a campus friend or send an invitation.": "\u53ef\u4ee5\u968f\u610f\u6d4f\u89c8\u6e38\u620f\u3002\u767b\u5f55\u540e\u5373\u53ef\u521b\u5efa\u623f\u95f4\u3001\u52a0\u5165\u540c\u6821\u597d\u53cb\u6216\u53d1\u9001\u9080\u8bf7\u3002",
  "Sign in to join": "\u767b\u5f55\u540e\u52a0\u5165",
  "A little more campus life.": "\u591a\u4e00\u70b9\u6821\u56ed\u751f\u6d3b\u3002",
  "Sign in to join your campus community.": "\u767b\u5f55\u540e\u52a0\u5165\u4f60\u7684\u6821\u56ed\u793e\u533a\u3002",
  "More campus. More connection.": "\u66f4\u591a\u6821\u56ed\uff0c\u66f4\u591a\u8fde\u63a5\u3002",
  "A place for your plans, your people and the things you want to show up for.": "\u5b89\u653e\u4f60\u7684\u8ba1\u5212\u3001\u4f60\u7684\u4f19\u4f34\uff0c\u4ee5\u53ca\u4f60\u60f3\u53bb\u53c2\u52a0\u7684\u4e8b\u60c5\u3002",
  "A campus full of possibilities.": "\u5145\u6ee1\u53ef\u80fd\u7684\u6821\u56ed\u3002",
  "Explore published activities. Exact markers appear once the organiser has saved a location.": "\u6d4f\u89c8\u5df2\u53d1\u5e03\u7684\u6d3b\u52a8\u3002\u7ec4\u7ec7\u8005\u4fdd\u5b58\u4e86\u4f4d\u7f6e\u540e\uff0c\u5730\u56fe\u4e0a\u624d\u4f1a\u663e\u793a\u7cbe\u786e\u6807\u8bb0\u3002",
  "Unpinned activities are listed by their published venue; they are not placed at invented coordinates. Test notices stay clearly labelled. Map tiles \u00a9 OpenStreetMap contributors.": "\u672a\u6807\u8bb0\u4f4d\u7f6e\u7684\u6d3b\u52a8\u6309\u516c\u5e03\u7684\u5730\u70b9\u5217\u51fa\uff0c\u4e0d\u4f1a\u88ab\u653e\u5728\u7f16\u9020\u7684\u5750\u6807\u4e0a\u3002\u6d4b\u8bd5\u901a\u77e5\u59cb\u7ec8\u6709\u660e\u786e\u6807\u6ce8\u3002\u5730\u56fe\u56fe\u5757 \u00a9 OpenStreetMap \u8d21\u732e\u8005\u3002",
  "A little room in your week.": "\u7ed9\u4f60\u7684\u4e00\u5468\u7559\u70b9\u7a7a\u95f4\u3002",
  "Bookings, saved events and scheduled screenings. Times follow your campus.": "\u62a5\u540d\u3001\u6536\u85cf\u7684\u6d3b\u52a8\u548c\u9884\u5b9a\u7684\u653e\u6620\u3002\u65f6\u95f4\u6309\u4f60\u7684\u6821\u56ed\u65f6\u533a\u663e\u793a\u3002",
  "Mon": "\u5468\u4e00",
  "Tue": "\u5468\u4e8c",
  "Wed": "\u5468\u4e09",
  "Thu": "\u5468\u56db",
  "Fri": "\u5468\u4e94",
  "Sat": "\u5468\u516d",
  "Sun": "\u5468\u65e5",
  "Overlapping confirmed plans. Saved events are tentative; fictional test notices do not create conflicts.": "\u5df2\u786e\u8ba4\u7684\u5b89\u6392\u6709\u65f6\u95f4\u51b2\u7a81\u3002\u6536\u85cf\u7684\u6d3b\u52a8\u53ea\u662f\u6682\u5b9a\uff1b\u865a\u6784\u7684\u6d4b\u8bd5\u901a\u77e5\u4e0d\u4f1a\u9020\u6210\u51b2\u7a81\u3002",
  "A little breathing room.": "\u7559\u4e00\u70b9\u5598\u606f\u7684\u7a7a\u95f4\u3002",
  "No saved plans in this month.": "\u8fd9\u4e2a\u6708\u8fd8\u6ca1\u6709\u5b89\u6392\u3002",
  "Your ideas. Your people.": "\u4f60\u7684\u70b9\u5b50\uff0c\u4f60\u7684\u4f19\u4f34\u3002",
  "Manage bookings, check people in and see how your activities are doing.": "\u7ba1\u7406\u62a5\u540d\u3001\u7b7e\u5230\uff0c\u5e76\u67e5\u770b\u4f60\u7684\u6d3b\u52a8\u60c5\u51b5\u3002",
  "Views": "\u6d4f\u89c8",
  "Confirmed": "\u5df2\u786e\u8ba4",
  "Waitlist": "\u5019\u8865",
  "Checked in": "\u5df2\u7b7e\u5230",
  "Search for a friend to get started.": "\u641c\u7d22\u4e00\u4f4d\u670b\u53cb\u5f00\u59cb\u5427\u3002",
  "Your conversations start here.": "\u4f60\u7684\u5bf9\u8bdd\u4ece\u8fd9\u91cc\u5f00\u59cb\u3002",
  "Good company. Shared goals.": "\u597d\u4f19\u4f34\uff0c\u5171\u540c\u7684\u76ee\u6807\u3002",
  "Find a study partner, a team mate or the missing piece of your next project.": "\u627e\u4e00\u4f4d\u5b66\u4e60\u4f19\u4f34\u3001\u961f\u53cb\uff0c\u6216\u8005\u4f60\u4e0b\u4e00\u4e2a\u9879\u76ee\u7f3a\u7684\u90a3\u4e2a\u4eba\u3002",
  "Your next team starts with you.": "\u4f60\u7684\u4e0b\u4e00\u652f\u961f\u4f0d\u4ece\u4f60\u5f00\u59cb\u3002",
  "Your communities, closer.": "\u8ba9\u4f60\u7684\u793e\u7fa4\u66f4\u8fd1\u4e00\u70b9\u3002",
  "New linked activities from followed clubs appear here.": "\u4f60\u5173\u6ce8\u7684\u793e\u56e2\u53d1\u5e03\u7684\u65b0\u6d3b\u52a8\u4f1a\u663e\u793a\u5728\u8fd9\u91cc\u3002",
  "Make the next watch a date.": "\u628a\u4e0b\u4e00\u6b21\u4e00\u8d77\u770b\u5b9a\u4e0b\u6765\u3002",
  "Plan a screening, invite your campus, and let the countdown begin.": "\u5b89\u6392\u4e00\u573a\u653e\u6620\uff0c\u9080\u8bf7\u540c\u6821\u540c\u5b66\uff0c\u5f00\u59cb\u5012\u8ba1\u65f6\u3002",
  "A shared screen starts with a plan.": "\u4e00\u8d77\u770b\uff0c\u4ece\u4e00\u4e2a\u8ba1\u5212\u5f00\u59cb\u3002",
  "A little friendly competition.": "\u6765\u70b9\u53cb\u597d\u7684\u6bd4\u8d5b\u3002",
  "Your campus, your games. Scores come only from completed server-validated matches.": "\u4f60\u7684\u6821\u56ed\uff0c\u4f60\u7684\u6e38\u620f\u3002\u6210\u7ee9\u53ea\u6765\u81ea\u670d\u52a1\u5668\u9a8c\u8bc1\u8fc7\u7684\u5b8c\u6574\u5bf9\u5c40\u3002",
  "Draws": "\u5e73\u5c40",
  "Losses": "\u8d1f",
  "The first match is yours.": "\u7b2c\u4e00\u573a\u6bd4\u8d5b\u7b49\u4f60\u6765\u3002",
  "The little things that matter.": "\u91cd\u8981\u7684\u5c0f\u4e8b\u3002",
  "Your invitations, conversations, bookings and campus updates.": "\u4f60\u7684\u9080\u8bf7\u3001\u5bf9\u8bdd\u3001\u62a5\u540d\u548c\u6821\u56ed\u52a8\u6001\u3002",
  "All caught up.": "\u5168\u90e8\u770b\u5b8c\u4e86\u3002",
  "Your next campus moment will find you here.": "\u4e0b\u4e00\u4e2a\u6821\u56ed\u65f6\u523b\u4f1a\u51fa\u73b0\u5728\u8fd9\u91cc\u3002",
  "Tap Save event on a poster to keep it here. Unpublished notices stay private.": "\u5728\u6d77\u62a5\u4e0a\u70b9\u201c\u6536\u85cf\u6d3b\u52a8\u201d\u5373\u53ef\u4fdd\u5b58\u5230\u8fd9\u91cc\u3002\u672a\u53d1\u5e03\u7684\u901a\u77e5\u4ecd\u662f\u79c1\u5bc6\u7684\u3002",
  "Times are local to campus. No time listed; the calendar entry will be all day.": "\u65f6\u95f4\u4e3a\u6821\u56ed\u5f53\u5730\u65f6\u95f4\u3002\u672a\u6ce8\u660e\u65f6\u95f4\uff0c\u65e5\u5386\u4e2d\u5c06\u663e\u793a\u4e3a\u5168\u5929\u6d3b\u52a8\u3002",
  "Your event, your people.": "\u4f60\u7684\u6d3b\u52a8\uff0c\u4f60\u7684\u4f19\u4f34\u3002",
